import{_ as o,a as r}from"./chunks/api2.Dw9IoJLQ.js";import{_ as i,o as s,c as l,a5 as n,j as e,a as t}from"./chunks/framework.DvE3tBec.js";const w=JSON.parse('{"title":"openEO proves its concept","description":"","frontmatter":{"news":true,"title":"openEO proves its concept","date":"2018-03-17T00:00:00.000Z","author":"Edzer Pebesma, the openEO consortium","aside":false},"headers":[],"relativePath":"news/2018-03-15-poc.md","filePath":"news/2018-03-15-poc.md","lastUpdated":1610116167000}'),c={name:"news/2018-03-15-poc.md"};function d(h,a,p,u,b,f){return s(),l("div",null,[...a[0]||(a[0]=[n('<h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The problem&quot;">​</a></h2><p>Earth Observation data are becoming too large to be downloaded locally for analysis. Also, the way they are organised (as tiles, or <em>granules</em>: files containing the imagery for a small part of the Earth and a single observation date) makes it unnecessary complicated to analyse them. The solution to this is to store these data in the cloud, on compute back-ends, process them there, and browse the results or download resulting figures or numbers. But how do we do that?</p><p>The aim of openEO is to develop an open API to connect R, python and javascript clients to big Earth observation cloud back-ends in a simple and unified way.</p><p>With such an API,</p><ul><li>each client can work with every back-end, and</li><li>it becomes possible to compare back-ends in terms of capacity, cost, and results (validation, reproducibility)</li></ul><h2 id="why-an-api" tabindex="-1">Why an API? <a class="header-anchor" href="#why-an-api" aria-label="Permalink to &quot;Why an API?&quot;">​</a></h2><p>An API is an application programming interface. It <em>defines</em> a <em>language</em> that two computers (a client and a server) use to communicate.</p><p>The following figure shows how many interfaces are needed to be able to compare back-ends from different clients, without an openEO API:</p><p><img src="'+o+'" alt="Current situation, without openEO API"></p><p>With an openEO API (dark blue), the situation becomes much easier:</p><p><img src="'+r+'" alt="Situation in the future, with openEO API"></p><p>However, existing back-ends need to be taught to work with the new API, and clients that interact with back-ends need to be developed.</p><p>The task of the openEO project is to design, develop, and evaluate an API for cloud-based Earth Observation data processing.</p><h2 id="first-results" tabindex="-1">First results <a class="header-anchor" href="#first-results" aria-label="Permalink to &quot;First results&quot;">​</a></h2><p>The openEO project started in Oct 2017. Now, within 6 months, we finished the first proof of concept, and demonstrate it. Three use cases were selected for this, three clients were developed pretty much from scratch (Python, R, and JavaScript), and seven back-ends were built or interfaced. Full information is available from the projects <a href="https://github.com/Open-EO/" target="_blank" rel="noreferrer">github organisation</a>, and we point here to the</p><ul><li>swagger-2.0 complient <a href="https://github.com/Open-EO/openeo-api" target="_blank" rel="noreferrer">API</a> and its <a href="https://open-eo.github.io/openeo-api/" target="_blank" rel="noreferrer">documentation</a></li></ul><h2 id="the-three-use-cases" tabindex="-1">The three use cases <a class="header-anchor" href="#the-three-use-cases" aria-label="Permalink to &quot;The three use cases&quot;">​</a></h2><p>The three use cases comprise</p><ol><li>Derive minimum NDVI measurements over pixel time series of Sentinel 2 imagery</li><li>Create a monthly aggregated Sentinel 1 product from a custom Python script</li><li>Compute time series of zonal (regional) statistics of Sentinel 2 imagery over user-uploaded polygons</li></ol><p>The full description, including the consecutive interaction steps of the API, is found on the</p><ul><li>proof-of-concept <a href="https://open-eo.github.io/openeo-api/poc/index.html" target="_blank" rel="noreferrer">use cases</a> site</li></ul><h2 id="links-to-the-client-and-back-end-implementations" tabindex="-1">Links to the client and back-end implementations <a class="header-anchor" href="#links-to-the-client-and-back-end-implementations" aria-label="Permalink to &quot;Links to the client and back-end implementations&quot;">​</a></h2><p>Clients:</p><ul><li><a href="https://github.com/Open-EO/openeo-python-client" target="_blank" rel="noreferrer">Python client</a>; <a href="https://github.com/Open-EO/openeo-python-client/blob/master/examples/notebooks/Compositing.ipynb" target="_blank" rel="noreferrer">Example notebook</a></li><li><a href="https://github.com/Open-EO/openeo-r-client" target="_blank" rel="noreferrer">R client</a></li><li><a href="https://github.com/Open-EO/openeo-js-client" target="_blank" rel="noreferrer">Javascript client</a> and <a href="https://github.com/Open-EO/openeo-web-editor" target="_blank" rel="noreferrer">JavaScript web editor</a></li></ul><p>Back-ends</p><ul><li><a href="https://open-eo.github.io/openeo-grassgis-driver/" target="_blank" rel="noreferrer">GRASS GIS driver</a></li><li><a href="https://github.com/Open-EO/openeo-wcps-driver" target="_blank" rel="noreferrer">WCPS driver</a></li><li><a href="https://github.com/Open-EO/openeo-openshift-driver" target="_blank" rel="noreferrer">OpenShift driver</a></li><li><a href="https://github.com/Open-EO/openeo-geopyspark-driver" target="_blank" rel="noreferrer">Python GeoPySpark/GeoTrellis driver</a></li><li><a href="https://github.com/Open-EO/openeo-sentinelhub-driver" target="_blank" rel="noreferrer">Sentinel Hub driver</a></li><li><a href="https://github.com/Open-EO/openeo-earthengine-driver" target="_blank" rel="noreferrer">Google Earth Engine back-end</a></li><li><a href="https://github.com/Open-EO/openeo-r-backend" target="_blank" rel="noreferrer">R back-end</a> (developed for testing purposes)</li></ul><p>With all this, you can install your own back-end of choice, install a client, and start analysing the data! (but do read &quot;Next steps&quot;, below). Alternatively, we show a couple of videos of screen casts made while testing the various clients and back-ends.</p><h2 id="proof-of-concept-videos" tabindex="-1">Proof-of-concept videos <a class="header-anchor" href="#proof-of-concept-videos" aria-label="Permalink to &quot;Proof-of-concept videos&quot;">​</a></h2><h3 id="r-client-and-wcps-back-end-use-case-1" tabindex="-1">R client and WCPS back-end, use case 1 <a class="header-anchor" href="#r-client-and-wcps-back-end-use-case-1" aria-label="Permalink to &quot;R client and WCPS back-end, use case 1&quot;">​</a></h3>',29),e("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/NoD0nVGM3ww",frameborder:"0",allowfullscreen:""},null,-1),e("h3",{id:"grass-gis-back-end-use-cases-1-2-and-3",tabindex:"-1"},[t("Grass GIS back-end, use cases 1, 2 and 3 "),e("a",{class:"header-anchor",href:"#grass-gis-back-end-use-cases-1-2-and-3","aria-label":'Permalink to "Grass GIS back-end, use cases 1, 2 and 3"'},"​")],-1),e("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/NgF1WgCtSiM",frameborder:"0",allowfullscreen:""},null,-1),e("h3",{id:"r-client-and-r-back-end-use-case-1",tabindex:"-1"},[t("R client and R back-end, use-case 1 "),e("a",{class:"header-anchor",href:"#r-client-and-r-back-end-use-case-1","aria-label":'Permalink to "R client and R back-end, use-case 1"'},"​")],-1),e("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/Yb_QflO-ulE",frameborder:"0",allowfullscreen:""},null,-1),e("h3",{id:"r-client-and-r-back-end-use-case-3",tabindex:"-1"},[t("R client and R back-end, use case 3 "),e("a",{class:"header-anchor",href:"#r-client-and-r-back-end-use-case-3","aria-label":'Permalink to "R client and R back-end, use case 3"'},"​")],-1),e("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/LYnad6KC_CU",frameborder:"0",allowfullscreen:""},null,-1),e("h3",{id:"openeo-web-editor-js-client-with-three-back-ends-use-case-1",tabindex:"-1"},[t("openEO Web Editor (JS client) with three back-ends (use case 1) "),e("a",{class:"header-anchor",href:"#openeo-web-editor-js-client-with-three-back-ends-use-case-1","aria-label":'Permalink to "openEO Web Editor (JS client) with three back-ends (use case 1)"'},"​")],-1),e("p",null,"Demonstrates use of back-ends Sentinel Hub, WCPS EURAC, and OpenShift EODC",-1),e("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/zDaQkw0NhpY",frameborder:"0",allowfullscreen:""},null,-1),e("h3",{id:"openeo-web-editor-js-client-with-r-back-end-use-case-3",tabindex:"-1"},[t("openEO Web Editor (JS client) with R back-end (use case 3) "),e("a",{class:"header-anchor",href:"#openeo-web-editor-js-client-with-r-back-end-use-case-3","aria-label":'Permalink to "openEO Web Editor (JS client) with R back-end (use case 3)"'},"​")],-1),e("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/XsPbKypUuIE",frameborder:"0",allowfullscreen:""},null,-1),e("h3",{id:"python-client-with-geopyspark-back-end-use-case-1",tabindex:"-1"},[t("Python client with GeoPySpark back-end (use case 1) "),e("a",{class:"header-anchor",href:"#python-client-with-geopyspark-back-end-use-case-1","aria-label":'Permalink to "Python client with GeoPySpark back-end (use case 1)"'},"​")],-1),e("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/qtIp9OC0qHY",frameborder:"0",allowfullscreen:""},null,-1),e("h3",{id:"openeo-web-editor-js-client-with-google-earth-engine-back-end-use-case-1",tabindex:"-1"},[t("openEO Web Editor (JS client) with Google Earth Engine back-end (use case 1) "),e("a",{class:"header-anchor",href:"#openeo-web-editor-js-client-with-google-earth-engine-back-end-use-case-1","aria-label":'Permalink to "openEO Web Editor (JS client) with Google Earth Engine back-end (use case 1)"'},"​")],-1),e("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/LmUlmsIGJrs",frameborder:"0",allowfullscreen:""},null,-1),n('<h2 id="links-to-documents" tabindex="-1">Links to documents <a class="header-anchor" href="#links-to-documents" aria-label="Permalink to &quot;Links to documents&quot;">​</a></h2><p>The following four documents (formal project deliverables) describe the proof-of-concept more extensively:</p><ul><li><a href="http://pebesma.staff.ifgi.de/openeo_del/openEO_D04_CoreAPIPrototype_v1.0.pdf" target="_blank" rel="noreferrer">openEO core API prototype including Proof of Concept</a></li><li><a href="http://pebesma.staff.ifgi.de/openeo_del/openEO_D06_PrototypeBackEnds_v1.0.pdf" target="_blank" rel="noreferrer">Two early prototype back-ends</a></li><li><a href="http://pebesma.staff.ifgi.de/openeo_del/openEO_D07_ProofOfConcept_v1.0.pdf" target="_blank" rel="noreferrer">Proof of Concept (Python)</a></li></ul><p>In addition, a document has been written that describes standards and interfaces used by the various back-ends, and the extent to which they are or will be useful for further developing the openEO API:</p><ul><li><a href="http://pebesma.staff.ifgi.de/openeo_del/openEO_D05_BackOfficeStandards_v1.0.pdf" target="_blank" rel="noreferrer">Overview document about back offices metadata standards and interfaces</a></li></ul><p>These deliverables have been submitted, but have not been approved, and hence may not be final.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><p>During the proof-of-concept, intentionally a number of difficult issues were not addressed, including</p><ul><li>billing (costs) of processes and account management and</li><li>authentification while others were defined rather vaguely, including</li><li>the description of data (end point <code>/data</code>)</li><li>the description of processes (end point <code>/processes</code>).</li></ul><p>The next steps will include:</p><ul><li>discussing of the use-cases in the proof-of-concept</li><li>deciding whether to adopt existing standards and interfaces, e.g. for data descriptions</li><li>getting users involved outside the openEO consortium to define further requirements and priorities</li><li>designing a new iteration of the openEO API.</li></ul><h2 id="getting-involved" tabindex="-1">Getting involved <a class="header-anchor" href="#getting-involved" aria-label="Permalink to &quot;Getting involved&quot;">​</a></h2><p>As any API, the openAPI will only become good and useful if it is being used, and it needs testing by a wide audience. We are now at the stage of designing it, but at the point where large chunks are useful already. If you want to contribute to any of this, please do not hesitate and contact us e.g. by</p><ul><li>expressing interest</li><li>writing GitHub issues wherever you think it is appropriate</li><li>sending an <a href="mailto:openeo.psc@uni-muenster.de" target="_blank" rel="noreferrer">email</a></li></ul>',14)])])}const k=i(c,[["render",d]]);export{w as __pageData,k as default};
